<script setup lang="ts">import { ref } from 'vue'; import { useRouter } from 'vue-router'; import UserForm from '@/components/UserForm.vue'; import { useUsersStore } from '@/stores/users'; import type { CreateUserDto } from '@/types/user'; const store = useUsersStore(), router = useRouter(), error = ref(''); async function submit(data: CreateUserDto) { try { const user = await store.create(data); router.push(`/users/${user.id}`) } catch (e) { error.value = e instanceof Error ? e.message : 'Помилка' } }</script>
<template><div class="page-heading"><div><p class="eyebrow">CREATE</p><h1>Новий користувач</h1></div></div><div v-if="error" class="alert alert-danger">{{ error }}</div><UserForm submit-label="Створити" include-password @submit="submit"/></template>
